actions.action:
wiz_step: f.wiz_step, wiz_stepper: f.wiz_stepper, wiz_heading: f.wiz_heading,
wiz_hint: f.wiz_hint, wiz_error: f.wiz_error, inner: f.inner,
btn_back: f.btn_back, btn_next: f.btn_next, btn_submit: f.btn_submit,
req_name: f.req_name, req_email: f.req_email;

changeCaseProperty("title").about { "Nová požiadavka" }

// Prihlasenemu cloveku netreba pisat, kto je. `isRealUser` odlisi skutocny
// ucet od anonyma a od systemoveho uctu - anonymna session ma tiez `loggedUser`,
// takze bez tejto podmienky by sa do kontaktu zapisalo "anonymous@netgrif.com"
// a operator by mal komu odpovedat len teoreticky.
def u = loggedUser()
if (isRealUser(u)) {
    change req_name value {
        (u.hasProperty("fullName") && u.fullName) ? (u.fullName as String) : (u.email as String)
    }
    change req_email value { u.email as String }
}

change wiz_step value { 1 }
change wiz_stepper value { stepper_label(1) }
change wiz_heading value { step_heading(1) }
change wiz_hint value { step_hint(1) }
change wiz_error value { "" }

def t = findTask { it.transitionId.eq("t_s_category").and(it.caseId.eq(useCase.stringId)) }
if (t) {
    assignTask(t)
    change inner value { [t.stringId] }
}
// Viditelnost navigacie podla kroku. Bez tohto by Spat svietilo na prvom
// kroku a Odoslat na kazdom.
make btn_back, hidden on transitions when { return 1 <= 1 }
make btn_back, editable on transitions when { return 1 > 1 }
make btn_next, hidden on transitions when { return 1 < 2 || 1 >= 4 }
make btn_next, editable on transitions when { return 1 >= 2 && 1 < 4 }
make btn_submit, hidden on transitions when { return 1 != 4 }
make btn_submit, editable on transitions when { return 1 == 4 }

document.function:
{ def caseObj ->
    // Na single-tenant nasadeni premenna workspace neexistuje a processIdentifier
    // je bez prefixu. Odvodime ho z vlastneho casu - jedina cesta, ktora funguje
    // aj v anonymnom kontexte.
    def pid = caseObj.processIdentifier
    return pid.contains("/") ? pid.substring(0, pid.lastIndexOf("/") + 1) : ""
}

{ def target, def caseObj ->
    // Vrati task podformulara pre dany krok a priradi ho. Zamerne NEmeni ziadne
    // pole: `change` volany vnutri procesovej funkcie sa zapise do databazy, ale
    // engine ho neoznaci ako zmeneny v odpovedi, takze prehliadac o zmene nevie
    // a vnoreny formular sa nepreklopi. Vsetky `change` preto zostavaju v akcii.
    def t = findTask { it.transitionId.eq(sub_transition(target)).and(it.caseId.eq(caseObj.stringId)) }
    if (!t) return null
    assignTask(t)
    return t.stringId
}

{ def step ->
    // Textovy stepper. Vyplneny kruzok = hotovy krok, polovicny = aktualny.
    int s = (step as Number).intValue()
    def names = ["Kategória", "Popis", "Kontakt", "Súhrn"]
    def parts = []
    for (int i = 1; i <= 4; i++) {
        def mark = (i < s) ? "●" : (i == s ? "◉" : "○")
        parts.add(mark + " " + i + ". " + names[i - 1])
    }
    return parts.join("      →      ")
}

{ def code ->
    def m = ["incident": "Nahlásiť poruchu", "service": "Servisný zásah",
             "change": "Žiadosť o zmenu", "access": "Prístup do systému",
             "question": "Otázka"]
    return m[code as String] ?: ""
}

{ def code ->
    def m = ["portal": "Zákaznícky portál", "core": "Hlavná aplikácia",
             "integration": "Integrácia s iným systémom", "reports": "Reporty a exporty",
             "account": "Účet a prihlásenie", "unknown": "Neviem určiť"]
    return m[code as String] ?: ""
}

{ def code ->
    def m = ["A": "A - blokuje to prácu", "B": "B - obmedzuje, ale dá sa pokračovať",
             "C": "C - počká"]
    return m[code as String] ?: ""
}

actions.action:
wiz_step: f.wiz_step, wiz_stepper: f.wiz_stepper, wiz_heading: f.wiz_heading,
wiz_hint: f.wiz_hint, wiz_error: f.wiz_error, inner: f.inner,
btn_back: f.btn_back, btn_next: f.btn_next, btn_submit: f.btn_submit;

int s = ((wiz_step.value ?: 1) as Number).intValue()
if (s > 1 && s < 5) {
    int target = s - 1
    def t = findTask { it.transitionId.eq(sub_transition(target)).and(it.caseId.eq(useCase.stringId)) }
    if (t) {
        assignTask(t)
        change inner value { [t.stringId] }
        change wiz_step value { target }
        change wiz_stepper value { stepper_label(target) }
        change wiz_heading value { step_heading(target) }
        change wiz_hint value { step_hint(target) }
        change wiz_error value { "" }

// Viditelnost navigacie podla kroku. Bez tohto by Spat svietilo na prvom
// kroku a Odoslat na kazdom.
make btn_back, hidden on transitions when { return target <= 1 }
make btn_back, editable on transitions when { return target > 1 }
make btn_next, hidden on transitions when { return target < 2 || target >= 4 }
make btn_next, editable on transitions when { return target >= 2 && target < 4 }
make btn_submit, hidden on transitions when { return target != 4 }
make btn_submit, editable on transitions when { return target == 4 }
    }
}

wiz_step: f.wiz_step, wiz_stepper: f.wiz_stepper, wiz_heading: f.wiz_heading,
wiz_hint: f.wiz_hint, wiz_error: f.wiz_error, inner: f.inner, sum_text: f.sum_text,
btn_back: f.btn_back, btn_next: f.btn_next, btn_submit: f.btn_submit,
req_type: f.req_type, req_service: f.req_service, req_title: f.req_title,
req_description: f.req_description, req_severity: f.req_severity,
req_name: f.req_name, req_email: f.req_email, req_org: f.req_org,
req_consent: f.req_consent;

int s = ((wiz_step.value ?: 1) as Number).intValue()

// Bez tlacidla Dokoncit engine required nevynucuje, takze validujeme tu.
// Textove polia maju immediate="true", takze ich hodnota je na serveri uz
// pocas pisania a nie az po strate fokusu - inak by button citil prazdno.
def problem = null
if (s == 1) {
    if (!((req_type.value ?: "") as String).trim()) {
        problem = "Vyberte prosím jednu z možností."
    }
} else if (s == 2) {
    if (!((req_title.value ?: "") as String).trim()) {
        problem = "Doplňte krátky názov."
    } else if (((req_description.value ?: "") as String).trim().length() < 15) {
        problem = "Popíšte prosím situáciu aspoň jednou vetou."
    }
} else if (s == 3) {
    def mail = ((req_email.value ?: "") as String).trim()
    if (!((req_name.value ?: "") as String).trim()) {
        problem = "Doplňte meno."
    } else if (!mail.contains("@") || !mail.contains(".")) {
        problem = "Skontrolujte e-mail, na tento vám nedokážeme odpovedať."
    } else if (!((req_org.value ?: "") as String).trim()) {
        problem = "Doplňte organizáciu."
    } else if (req_consent.value != true) {
        problem = "Bez súhlasu so spracovaním údajov požiadavku spracovať nemôžeme."
    }
}

if (problem != null) {
    change wiz_error value { problem }
} else if (s < 4) {
    int target = s + 1
    def t = findTask { it.transitionId.eq(sub_transition(target)).and(it.caseId.eq(useCase.stringId)) }
    if (t) {
        assignTask(t)
        change inner value { [t.stringId] }
        change wiz_step value { target }
        change wiz_stepper value { stepper_label(target) }
        change wiz_heading value { step_heading(target) }
        change wiz_hint value { step_hint(target) }
        change wiz_error value { "" }

// Viditelnost navigacie podla kroku. Bez tohto by Spat svietilo na prvom
// kroku a Odoslat na kazdom.
make btn_back, hidden on transitions when { return target <= 1 }
make btn_back, editable on transitions when { return target > 1 }
make btn_next, hidden on transitions when { return target < 2 || target >= 4 }
make btn_next, editable on transitions when { return target >= 2 && target < 4 }
make btn_submit, hidden on transitions when { return target != 4 }
make btn_submit, editable on transitions when { return target == 4 }
        if (target == 4) {
            change sum_text value {
                "TYP POŽIADAVKY\n" + type_label(req_type.value) +
                "\n\nSLUŽBA\n" + service_label(req_service.value) +
                "\n\nNÁZOV\n" + ((req_title.value ?: "") as String) +
                "\n\nSÚRNOSŤ\n" + severity_label(req_severity.value) +
                "\n\nPOPIS\n" + ((req_description.value ?: "") as String) +
                "\n\nKONTAKT\n" + ((req_name.value ?: "") as String) +
                "  ·  " + ((req_email.value ?: "") as String) +
                "\n" + ((req_org.value ?: "") as String)
            }
        }
    }
}

wiz_step: f.wiz_step, wiz_stepper: f.wiz_stepper, wiz_heading: f.wiz_heading,
wiz_hint: f.wiz_hint, wiz_error: f.wiz_error, inner: f.inner,
btn_back: f.btn_back, btn_next: f.btn_next, btn_submit: f.btn_submit,
req_type: f.req_type, req_service: f.req_service, req_title: f.req_title,
req_description: f.req_description, req_severity: f.req_severity,
req_steps: f.req_steps, req_workaround: f.req_workaround, req_started: f.req_started,
req_affects_more: f.req_affects_more,
req_name: f.req_name, req_email: f.req_email, req_phone: f.req_phone, req_org: f.req_org,
ticket_number: f.ticket_number, ticket_case_id: f.ticket_case_id,
submitted_ok: f.submitted_ok, receipt_note: f.receipt_note;

int s = ((wiz_step.value ?: 1) as Number).intValue()
if (s == 4) {
    def payload = [
        "src_type"        : ["value": req_type.value, "type": "enumeration_map"],
        "src_service"     : ["value": req_service.value, "type": "enumeration_map"],
        "src_title"       : ["value": req_title.value, "type": "text"],
        "src_description" : ["value": req_description.value, "type": "text"],
        "src_severity"    : ["value": req_severity.value, "type": "enumeration_map"],
        "src_steps"       : ["value": req_steps.value, "type": "text"],
        "src_workaround"  : ["value": req_workaround.value, "type": "text"],
        "src_name"        : ["value": req_name.value, "type": "text"],
        "src_email"       : ["value": req_email.value, "type": "text"],
        "src_phone"       : ["value": req_phone.value, "type": "text"],
        "src_org"         : ["value": req_org.value, "type": "text"],
        "src_affects_more": ["value": req_affects_more.value, "type": "boolean"],
        "src_request_id"  : ["value": useCase.stringId, "type": "text"],
        "tk_priority"     : ["value": req_severity.value, "type": "enumeration_map"],
        "tk_type"         : ["value": req_type.value, "type": "enumeration_map"]
    ]
    if (req_started.value != null) {
        payload["src_started"] = ["value": req_started.value, "type": "dateTime"]
    }

    try {
        def ticket = createCase(net_prefix(useCase) + "sd_ticket")
        change ticket_case_id value { ticket.stringId }
        change ticket_number value { ticket.visualId ?: ticket.stringId }
        change submitted_ok value { true }
        change receipt_note value {
            "Požiadavku sme prijali. Potvrdenie posielame na " +
            ((req_email.value ?: "") as String) +
            ". Operátor podpory ju prevezme a ozve sa vám."
        }
        // Synchronne a v tom istom try: `async.run` vynimku spolkne, takze
        // zle prenesene pole by sa prejavilo ako prazdny tiket bez akejkolvek
        // stopy. Takto to zakaznik uvidi v chybovej sprave a operator v logu.
        setData("t_triage", ticket, payload)

        def t = findTask { it.transitionId.eq("t_s_receipt").and(it.caseId.eq(useCase.stringId)) }
        if (t) {
            assignTask(t)
            change inner value { [t.stringId] }
        }
        change wiz_step value { 5 }
        change wiz_stepper value { "● 1. Kategória      →      ● 2. Popis      →      ● 3. Kontakt      →      ● 4. Súhrn" }
        change wiz_heading value { step_heading(5) }
        change wiz_hint value { step_hint(5) }
        change wiz_error value { "" }
        changeCaseProperty("title").about { "Podané: " + ((req_title.value ?: "") as String) }

        make btn_back, hidden on transitions when { true }
        make btn_next, hidden on transitions when { true }
        make btn_submit, hidden on transitions when { true }
    } catch (Exception e) {
        change submitted_ok value { false }
        change wiz_error value {
            "Požiadavku sa nepodarilo odoslať. Skúste to prosím znova, alebo nám zavolajte a uveďte kód " +
            useCase.stringId + " (detail: " + e.message + ")"
        }
    }
}

